def src(i, title, url, kind='موسوعة مرجعية'):
    if i in S:
        return
    d['sources'].append({'id': i, 'title': title, 'url': url, 'accessed': ACC, 'type': kind,
                         'verification': 'روجعت الصفحة في 17 أكتوبر 2026؛ لا يعني ذلك تدقيقًا أكاديميًا شاملًا'})
    S.add(i)


