# أبرز الشخصيات في صفحات الحضارات
def people(civ, items, drop=()):
    c = C[civ]
    c['people'] = [x for x in c['people'] if x['id'] not in drop]
    have = {x['id'] for x in c['people']}
    for pid, role in items:
        if pid not in have:
            c['people'].append({'id': pid, 'name': E[pid]['title'], 'role': role, 'sourceIds': E[pid]['sourceIds']})

